from collections import deque

import jax
import jax.numpy as jnp
import numpy as np

from .group import Group


def subgroup_closure(group: Group, generators) -> np.ndarray:
    """The subgroup generated by `generators`, as a sorted array of element numbers."""
    generators = np.unique(np.asarray(generators, dtype=np.int64))
    inside = np.zeros(group.n, dtype=bool)
    inside[group.ed] = True
    frontier = np.array([group.ed])
    while len(frontier) > 0 and len(generators) > 0:
        products = np.unique(group.kaili[np.ix_(frontier, generators)])
        frontier = products[~inside[products]]
        inside[frontier] = True
    return np.flatnonzero(inside)


def subgroup_chain(group: Group) -> list[np.ndarray]:
    """A chain of subgroups `{e} = G_0 < G_1 < ... < G_m = G`, built greedily: each
    `G_i` is generated by `G_{i-1}` and one more element, chosen so that the index
    `[G_i : G_{i-1}]` is as small as possible.
    """
    chain = [np.array([group.ed])]
    generators = []
    while len(chain[-1]) < group.n:
        inside = np.zeros(group.n, dtype=bool)
        inside[chain[-1]] = True
        best = None
        for g in np.flatnonzero(~inside):
            candidate = subgroup_closure(group, generators + [g])
            if best is None or len(candidate) < len(best[1]):
                best = (int(g), candidate)
                if len(candidate) == 2 * len(chain[-1]):
                    break
        generators.append(best[0])
        chain.append(best[1])
    return chain


def convolution(group: Group, f, h):
    """The convolution `(f * h)(x) = sum_y f(y) h(y^{-1} x)`, computed directly in
    `O(n^2)` operations. Both arguments have shape `(..., n)`.
    """
    f = jnp.asarray(f)
    h = jnp.asarray(h)
    dtype = np.result_type(f.dtype, h.dtype)
    f = f.astype(dtype)
    h = h.astype(dtype)
    return jnp.einsum("...y,...yx->...x", f, h[..., group.kaili[group.inv]])


def _complex_dtype():
    return jnp.asarray(1j).dtype


class AbstractFourierTransform:
    """Fourier transform on a finite group `G` with respect to a complete set of
    unitary irreducible representations `rho_1, ..., rho_h`:

    `fhat(rho) = sum_g f(g) rho(g)`,

    `f(g) = (1/n) sum_rho d_rho tr(rho(g)^H fhat(rho))`.

    Functions on `G` are arrays of shape `(..., n)`; transforms are lists with one
    array of shape `(..., d_r, d_r)` per representation. The representations are
    computed once with NumPy; `forward` and `inverse` are JAX functions, so they can be
    used under `jax.jit`, `jax.vmap` and `jax.grad`.

    `to_coordinates` and `from_coordinates` convert to the real coordinates used to
    solve differential equations: the blocks `sqrt(d_rho / n) fhat(rho)`, split into
    real and imaginary parts. In these coordinates the transform is an isometry.
    """

    group: Group
    representations: list[np.ndarray]

    @property
    def degrees(self) -> np.ndarray:
        return np.array([rep.shape[1] for rep in self.representations])

    def forward(self, f) -> list:
        raise NotImplementedError

    def inverse(self, fhat):
        raise NotImplementedError

    def convolve(self, f, h):
        """The convolution `f * h`, through `(f * h)^(rho) = fhat(rho) hhat(rho)`."""
        fhat = self.forward(f)
        hhat = self.forward(h)
        return self.inverse([a @ b for a, b in zip(fhat, hhat)])

    def to_coordinates(self, f) -> tuple:
        """Real coordinates of `f`: a tuple with, for each representation, an array of
        shape `(2, ..., d, d)` holding the real and imaginary parts of
        `sqrt(d / n) fhat(rho)`.
        """
        n = self.group.n
        return tuple(
            jnp.stack([a.real, a.imag]) * float(np.sqrt(d / n))
            for a, d in zip(self.forward(f), self.degrees)
        )

    def from_coordinates(self, y):
        """The function on the group with real coordinates `y`."""
        n = self.group.n
        return self.inverse(
            [
                jax.lax.complex(b[0], b[1]) * float(np.sqrt(n / d))
                for b, d in zip(y, self.degrees)
            ]
        )

    def _check_function(self, f):
        f = jnp.asarray(f)
        if f.ndim == 0 or f.shape[-1] != self.group.n:
            raise ValueError(
                f"Functions on the group must have shape (..., {self.group.n})."
            )
        return f.astype(_complex_dtype())

    def _check_transform(self, fhat) -> list:
        fhat = [jnp.asarray(a).astype(_complex_dtype()) for a in fhat]
        if len(fhat) != len(self.representations):
            raise ValueError(
                f"Expected {len(self.representations)} Fourier coefficients."
            )
        batch = fhat[0].shape[:-2]
        for a, d in zip(fhat, self.degrees):
            if a.shape != batch + (d, d):
                raise ValueError("Fourier coefficients have inconsistent shapes.")
        return fhat


class FourierTransform(AbstractFourierTransform):
    """The Fourier transform computed directly from its definition, in `O(n^2)`
    operations.

    **Arguments:**

    - `group`: the group.
    - `representations`: unitary irreducible representations, each of shape
        `(n, d, d)`. Defaults to `group.irreducible_representations()`.
    - `seed`: seed for computing the representations.
    """

    def __init__(self, group: Group, representations=None, seed: int = 0):
        if representations is None:
            representations = group.irreducible_representations(seed)
        representations = [np.asarray(r, dtype=np.complex128) for r in representations]
        for rep in representations:
            if rep.ndim != 3 or rep.shape[0] != group.n or rep.shape[1] != rep.shape[2]:
                raise ValueError("Representations must have shape (n, d, d).")
        if sum(rep.shape[1] ** 2 for rep in representations) != group.n:
            raise ValueError("Representations are not a complete set: sum d^2 != n.")
        self.group = group
        self.representations = representations

    def forward(self, f) -> list:
        f = self._check_function(f)
        return [
            jnp.einsum("...g,gij->...ij", f, rep.astype(f.dtype))
            for rep in self.representations
        ]

    def inverse(self, fhat):
        fhat = self._check_transform(fhat)
        n = self.group.n
        return sum(
            (rep.shape[1] / n)
            * jnp.einsum("...ij,gij->...g", a, rep.conj().astype(a.dtype))
            for a, rep in zip(fhat, self.representations)
        )


class _SparseMatrix:
    def __init__(self, matrix: np.ndarray, atol: float):
        matrix = np.asarray(matrix, dtype=np.complex128)
        rows, cols = np.nonzero(np.abs(matrix) > atol)
        self.shape = matrix.shape
        self.nnz = len(rows)
        self.dense = matrix if self.nnz > matrix.size // 4 else None
        self.rows = rows
        self.cols = cols
        self.vals = matrix[rows, cols]

    def __matmul__(self, x):
        if self.dense is not None:
            return self.dense.astype(x.dtype) @ x
        products = self.vals.astype(x.dtype)[:, None] * x[..., self.cols, :]
        out = jnp.zeros(x.shape[:-2] + (self.shape[0], x.shape[-1]), dtype=x.dtype)
        return out.at[..., self.rows, :].add(products)


class _Level:
    def __init__(self, elements, index, transversal, parents, factors, cosets):
        self.elements = elements
        self.index = index
        self.transversal = transversal
        self.parents = parents
        self.factors = factors
        self.cosets = cosets
        self.representations = []
        self.blocks = []
        self.matrices = []
        self.adjoints = []


def _check_chain(group: Group, chain) -> list[np.ndarray]:
    chain = [np.unique(np.asarray(c, dtype=np.int64)) for c in chain]
    if len(chain) == 0 or not np.array_equal(chain[0], [group.ed]):
        raise ValueError("A subgroup chain must start with the trivial subgroup {e}.")
    if len(chain[-1]) != group.n:
        raise ValueError("A subgroup chain must end with the whole group.")
    for small, large in zip(chain[:-1], chain[1:]):
        if len(small) >= len(large) or not np.isin(small, large).all():
            raise ValueError("A subgroup chain must be strictly increasing.")
    for c in chain:
        if not np.isin(group.kaili[np.ix_(c, c)], c).all():
            raise ValueError("Every member of a subgroup chain must be a subgroup.")
    return chain


def _generators(group: Group, chain) -> list[list[int]]:
    generators = [[]]
    for subgroup in chain[1:]:
        current = list(generators[-1])
        closure = subgroup_closure(group, current)
        while len(closure) < len(subgroup):
            current.append(int(np.setdiff1d(subgroup, closure)[0]))
            closure = subgroup_closure(group, current)
        generators.append(current)
    return generators


def _transversal_tree(group: Group, elements, subgroup, generators) -> _Level:
    index = len(elements) // len(subgroup)
    label = np.full(group.n, -1, dtype=np.int64)
    label[elements] = group.kaili[np.ix_(elements, subgroup)].min(axis=1)
    parent = {group.ed: None}
    order = [group.ed]
    representative = {label[group.ed]: group.ed}
    queue = deque([group.ed])
    while queue and len(representative) < index:
        t = queue.popleft()
        for u in generators:
            s = int(group.kaili[t, u])
            if s in parent:
                continue
            parent[s] = (t, u)
            order.append(s)
            queue.append(s)
            representative.setdefault(label[s], s)
    if len(representative) < index:
        raise ValueError("Generators do not reach every coset.")

    keep = set()
    for s in representative.values():
        while s is not None and s not in keep:
            keep.add(s)
            s = None if parent[s] is None else parent[s][0]
    nodes = [s for s in order if s in keep]
    node_index = {s: i for i, s in enumerate(nodes)}
    is_representative = set(representative.values())
    transversal = [s for s in nodes if s in is_representative]
    coset_index = {s: j for j, s in enumerate(transversal)}

    parents = np.array([-1] + [node_index[parent[s][0]] for s in nodes[1:]])
    factors = np.array([-1] + [parent[s][1] for s in nodes[1:]])
    cosets = np.array([coset_index.get(s, -1) for s in nodes])
    return _Level(elements, index, np.array(transversal), parents, factors, cosets)


def _adapt(rep, restriction, sub_representations, atol):
    restricted = rep[restriction]
    order = len(restriction)
    d = rep.shape[1]
    columns, blocks, offset = [], [], 0
    for index, sub in enumerate(sub_representations):
        e = sub.shape[1]
        overlap = np.einsum("hii,hjj->", restricted, sub.conj()) / order
        multiplicity = round(overlap.real)
        if abs(overlap - multiplicity) > 1e-6:
            raise RuntimeError("Restriction multiplicity is not an integer.")
        if multiplicity == 0:
            continue
        units = (e / order) * np.einsum("ha,hij->aij", sub[:, :, 0].conj(), restricted)
        eigvals, eigvecs = np.linalg.eigh((units[0] + units[0].conj().T) / 2)
        vectors = eigvecs[:, eigvals > 0.5]
        if vectors.shape[1] != multiplicity:
            raise RuntimeError(
                "Could not isolate the copies of a subgroup representation."
            )
        for c in range(multiplicity):
            columns.extend(units @ vectors[:, c])
            blocks.append((index, offset, e))
            offset += e
    basis = np.stack(columns, axis=1)
    if basis.shape != (d, d) or not np.allclose(
        basis.conj().T @ basis, np.eye(d), atol=atol
    ):
        raise RuntimeError("Adapted basis is not unitary.")
    adapted = basis.conj().T @ rep @ basis
    expected = np.zeros_like(restricted)
    for index, offset, e in blocks:
        expected[:, offset : offset + e, offset : offset + e] = sub_representations[
            index
        ]
    if not np.allclose(adapted[restriction], expected, atol=atol):
        raise RuntimeError("Adapted representation is not block diagonal.")
    return adapted, blocks


class FastFourierTransform(AbstractFourierTransform):
    """The fast Fourier transform along a chain of subgroups
    `{e} = G_0 < G_1 < ... < G_m = G` (separation of variables: Beth, Clausen,
    Maslen, Rockmore).

    The representations of every `G_i` are put in a basis adapted to the chain: for
    `h` in `G_{i-1}`, `rho(h)` is literally block diagonal, with blocks the adapted
    representations of `G_{i-1}`. With `G_i = t_1 G_{i-1} + ... + t_k G_{i-1}`,

    `fhat(rho) = sum_j rho(t_j) (+)_sigma fhat_j(sigma)`,

    where `fhat_j` is the transform over `G_{i-1}` of `f` restricted to the coset
    `t_j G_{i-1}`. Each transversal element is a word in generators of `G_i`, and the
    words form a tree, so the sum is evaluated by Horner's rule along the tree. The
    matrices of generators lying in `G_{i-1}` are block diagonal, and are applied as
    sparse matrices; for `S_n` with adjacent transpositions this is Clausen's
    algorithm.

    **Arguments:**

    - `group`: the group.
    - `chain`: a list of arrays of element numbers, strictly increasing subgroups from
        `{e}` to `G`. Defaults to `subgroup_chain(group)`.
    - `seed`: seed for computing irreducible representations.
    - `atol`: tolerance for the checks of the adapted bases, and below which matrix
        entries are treated as zero.
    """

    def __init__(self, group: Group, chain=None, seed: int = 0, atol: float = 1e-8):
        chain = subgroup_chain(group) if chain is None else _check_chain(group, chain)
        generators = _generators(group, chain)
        self.group = group
        self.chain = chain
        self.levels = []

        previous = [np.ones((1, 1, 1), dtype=np.complex128)]
        for i in range(1, len(chain)):
            elements, subgroup = chain[i], chain[i - 1]
            level = _transversal_tree(group, elements, subgroup, generators[i])
            local = np.full(group.n, -1, dtype=np.int64)
            local[elements] = np.arange(len(elements))
            if len(elements) == group.n:
                reps = group.irreducible_representations(seed)
            else:
                table = local[group.kaili[np.ix_(elements, elements)]]
                reps = Group(table, check=False).irreducible_representations(seed)
            factors = set(level.factors[1:].tolist())
            for rep in reps:
                adapted, blocks = _adapt(rep, local[subgroup], previous, atol)
                level.representations.append(adapted)
                level.blocks.append(blocks)
                level.matrices.append(
                    {u: _SparseMatrix(adapted[local[u]], atol) for u in factors}
                )
                level.adjoints.append(
                    {
                        u: _SparseMatrix(adapted[local[u]].conj().T, atol)
                        for u in factors
                    }
                )
            self.levels.append(level)
            previous = level.representations
        self.representations = previous

        order = np.array([group.ed])
        for level in reversed(self.levels):
            order = group.kaili[np.ix_(order, level.transversal)].reshape(-1)
        if not np.array_equal(np.sort(order), np.arange(group.n)):
            raise RuntimeError("Transversals do not factorise the group.")
        self.order = order
        self.unorder = np.argsort(order)

    def operation_count(self) -> int:
        """Number of complex multiplications in one forward transform."""
        count = 0
        cosets = self.group.n
        for level in self.levels:
            cosets //= level.index
            for matrices, rep in zip(level.matrices, level.representations):
                d = rep.shape[1]
                for u in level.factors[1:].tolist():
                    count += cosets * matrices[u].nnz * d
        return count

    def forward(self, f) -> list:
        f = self._check_function(f)
        batch = f.shape[:-1]
        n = self.group.n
        x = f.reshape(-1, n)[:, self.order]
        data = [x.reshape(x.shape[0], n, 1, 1)]
        for level in self.levels:
            pieces = [
                p.reshape(p.shape[0], -1, level.index, *p.shape[2:]) for p in data
            ]
            data = []
            for rep, blocks, matrices in zip(
                level.representations, level.blocks, level.matrices
            ):
                d = rep.shape[1]
                stacked = jnp.zeros(pieces[0].shape[:3] + (d, d), dtype=f.dtype)
                for index, offset, e in blocks:
                    stacked = stacked.at[
                        ..., offset : offset + e, offset : offset + e
                    ].set(pieces[index])
                sums = [None] * len(level.parents)
                for node in reversed(range(len(level.parents))):
                    total = sums[node]
                    coset = level.cosets[node]
                    if coset >= 0:
                        term = stacked[:, :, coset]
                        total = term if total is None else total + term
                    if node == 0:
                        data.append(total)
                    else:
                        term = matrices[int(level.factors[node])] @ total
                        parent = level.parents[node]
                        sums[parent] = (
                            term if sums[parent] is None else sums[parent] + term
                        )
        return [a.reshape(batch + a.shape[-2:]) for a in data]

    def inverse(self, fhat):
        fhat = self._check_transform(fhat)
        batch = fhat[0].shape[:-2]
        n = self.group.n
        dtype = fhat[0].dtype
        data = [(a.shape[-1] / n) * a.reshape(-1, 1, *a.shape[-2:]) for a in fhat]
        for i in reversed(range(len(self.levels))):
            level = self.levels[i]
            below = (
                self.levels[i - 1].representations if i > 0 else [np.ones((1, 1, 1))]
            )
            size = data[0].shape[:2]
            pieces = [
                jnp.zeros(size + (level.index, r.shape[1], r.shape[1]), dtype=dtype)
                for r in below
            ]
            for a, blocks, adjoints in zip(data, level.blocks, level.adjoints):
                values = [None] * len(level.parents)
                for node in range(len(level.parents)):
                    if node == 0:
                        values[node] = a
                    else:
                        values[node] = (
                            adjoints[int(level.factors[node])]
                            @ values[level.parents[node]]
                        )
                    coset = level.cosets[node]
                    if coset >= 0:
                        for index, offset, e in blocks:
                            pieces[index] = (
                                pieces[index]
                                .at[:, :, coset]
                                .add(
                                    values[node][
                                        ..., offset : offset + e, offset : offset + e
                                    ]
                                )
                            )
            data = [p.reshape(p.shape[0], -1, *p.shape[3:]) for p in pieces]
        x = data[0].reshape(-1, n)
        return x[:, self.unorder].reshape(batch + (n,))
